import{_ as e,o as n,c as a,a as r}from"./app.DLiRGumz.js";const h=JSON.parse('{"title":"Touchpoint Integration Evaluation","description":"","frontmatter":{},"headers":[],"relativePath":"reference/TOUCHPOINT_INTEGRATION_EVALUATION.md","filePath":"reference/TOUCHPOINT_INTEGRATION_EVALUATION.md","lastUpdated":1771835514000}'),s={name:"reference/TOUCHPOINT_INTEGRATION_EVALUATION.md"};function o(d,t,i,l,c,g){return n(),a("div",null,[...t[0]||(t[0]=[r(`<h1 id="touchpoint-integration-evaluation" tabindex="-1">Touchpoint Integration Evaluation <a class="header-anchor" href="#touchpoint-integration-evaluation" aria-label="Permalink to &quot;Touchpoint Integration Evaluation&quot;">​</a></h1><blockquote><p><strong>Purpose</strong>: Evaluate how MCP, CLI, skills, CLAUDE.md, roles, and headless triggers can be holistically tied into the unified work stream and team-structure/software-dev civilizational systems. Assess MD (read-only/short-throw) vs SQLite/DB-backed storage. <strong>Deep dive</strong>: <a href="./TOUCHPOINT_INTEGRATION_DEEP_DIVE.html">TOUCHPOINT_INTEGRATION_DEEP_DIVE.md</a> — related conversations, research index, <strong>web research</strong>, <strong>thegent copilot/sitback agents</strong>, ~/../project paths, cross-cutting flows, multi-platform, implementation roadmap.</p></blockquote><hr><h2 id="touchpoint-matrix" tabindex="-1">Touchpoint Matrix <a class="header-anchor" href="#touchpoint-matrix" aria-label="Permalink to &quot;Touchpoint Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Touchpoint</th><th>Location</th><th>Current State</th><th>Feeds Into</th><th>Consumes From</th></tr></thead><tbody><tr><td><strong>MCP tools</strong></td><td><code>mcp_server.py</code></td><td><code>thegent_do_next</code>, <code>thegent_run</code>, <code>thegent_bg</code>, etc.</td><td>Agent execution</td><td>WORK_STREAM, run_registry, escalation</td></tr><tr><td><strong>MCP resources</strong></td><td><code>thegent://*</code> URIs</td><td>workflow/triggers, workflow/gardening, sitback/dashboard, sessions, observe/summary</td><td>Agent context</td><td>run_registry, WORK_STREAM, contracts</td></tr><tr><td><strong>MCP prompts</strong></td><td><code>thegent_workflow_*</code></td><td>idea, quality_green, next_item, gardening</td><td>Structured invocation</td><td>WORK_STREAM, pending-handoff</td></tr><tr><td><strong>CLI</strong></td><td><code>main.py</code>, <code>cli.py</code></td><td><code>plan next</code>, <code>plan incorporate</code>, <code>govern go cycle</code>, <code>govern go health</code></td><td>Human/script invocation</td><td>Same as MCP</td></tr><tr><td><strong>Skills</strong></td><td><code>skills/*/SKILL.md</code></td><td>sitback-agent, agent-orchestra</td><td>Agent persona + workflow</td><td>CLAUDE.md, WORK_STREAM, gardening</td></tr><tr><td><strong>CLAUDE.md</strong></td><td>Root</td><td>Project instructions, workflow triggers table</td><td>All agents</td><td>—</td></tr><tr><td><strong>Roles</strong></td><td><code>agents/*.md</code></td><td>Persona definitions</td><td>Agent selection</td><td>CLAUDE.md</td></tr><tr><td><strong>Headless triggers</strong></td><td><code>governance/triggers.py</code>, <code>hooks/gardener-*.sh</code></td><td>Watchdog, timer, manual; gardener loop</td><td>AgilePlus cycle, gardener spawn</td><td>run_registry, backlog.jsonl, garden-state</td></tr></tbody></table><hr><h2 id="current-state-storage-file-backed" tabindex="-1">Current State Storage (File-Backed) <a class="header-anchor" href="#current-state-storage-file-backed" aria-label="Permalink to &quot;Current State Storage (File-Backed)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Store</th><th>Path</th><th>Format</th><th>Writers</th><th>Readers</th></tr></thead><tbody><tr><td>Work stream</td><td><code>docs/reference/WORK_STREAM.md</code></td><td>Markdown tables</td><td>Incorporator, agents (claim/complete)</td><td>do_next_impl, agents</td></tr><tr><td>Run registry</td><td><code>.thegent/sessions/run_registry.jsonl</code></td><td>JSONL</td><td>execution.py, mcp_server</td><td>MCP resources, CLI</td></tr><tr><td>Handoff registry</td><td><code>.thegent/sessions/handoff_registry.jsonl</code></td><td>JSONL</td><td>execution.py</td><td>handoff_show</td></tr><tr><td>AgilePlus backlog</td><td><code>.thegent/sessions/agileplus/backlog.jsonl</code></td><td>JSONL</td><td>BacklogManager</td><td>AgilePlusLoop</td></tr><tr><td>Evidence ledger</td><td><code>.thegent/sessions/agileplus/evidence_ledger.jsonl</code></td><td>JSONL (hash-chained)</td><td>EvidenceLedger</td><td>Audit</td></tr><tr><td>Garden state</td><td><code>contracts/garden-state.json</code></td><td>JSON</td><td>gardener-loop</td><td>gardener-scan</td></tr><tr><td>XP state</td><td><code>.thegent/gardener/xp/state.json</code></td><td>JSON</td><td>gardener-xp.sh</td><td>gardener-xp.sh</td></tr><tr><td>Pending handoff</td><td><code>docs/research/pending-handoff.md</code>, <code>~/.claude/pending-handoff.md</code></td><td>Markdown</td><td>Session stop hooks</td><td>do_next_impl</td></tr></tbody></table><hr><h2 id="md-as-read-only-short-throw" tabindex="-1">MD as Read-Only / Short-Throw <a class="header-anchor" href="#md-as-read-only-short-throw" aria-label="Permalink to &quot;MD as Read-Only / Short-Throw&quot;">​</a></h2><h3 id="pros" tabindex="-1">Pros <a class="header-anchor" href="#pros" aria-label="Permalink to &quot;Pros&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Benefit</th><th>Rationale</th></tr></thead><tbody><tr><td><strong>Git-friendly</strong></td><td>WORK_STREAM.md, specs/, plans/ diff and merge. No binary blobs.</td></tr><tr><td><strong>Human-readable</strong></td><td>Agents, humans, and tools can inspect and edit without tooling.</td></tr><tr><td><strong>Short-throw</strong></td><td>Edit in place; no sync layer. CLAUDE.md, skills, roles are already MD.</td></tr><tr><td><strong>Portable</strong></td><td>No DB runtime. Works in sandbox, CI, read-only mounts.</td></tr><tr><td><strong>Audit trail</strong></td><td>Git history = natural audit. JSONL append-only gives similar for events.</td></tr><tr><td><strong>Low friction</strong></td><td>No migrations, no connection pooling, no backup strategy beyond git.</td></tr></tbody></table><h3 id="cons" tabindex="-1">Cons <a class="header-anchor" href="#cons" aria-label="Permalink to &quot;Cons&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Drawback</th><th>Mitigation</th></tr></thead><tbody><tr><td><strong>Concurrent writes</strong></td><td>Multiple agents editing WORK_STREAM → conflict. Use claim file or single-writer (incorporator).</td></tr><tr><td><strong>No transactions</strong></td><td>Partial write can corrupt. Use atomic write (write to temp, rename).</td></tr><tr><td><strong>Query limits</strong></td><td>No SQL. Filtering/sorting done in code. Acceptable for backlog size (&lt;10k items).</td></tr><tr><td><strong>No foreign keys</strong></td><td>Depends, traceability manual. Schema discipline in incorporator.</td></tr></tbody></table><h3 id="verdict-md-jsonl-is-good-for-thegent-s-scale" tabindex="-1">Verdict: MD + JSONL is <strong>good</strong> for thegent&#39;s scale <a class="header-anchor" href="#verdict-md-jsonl-is-good-for-thegent-s-scale" aria-label="Permalink to &quot;Verdict: MD + JSONL is **good** for thegent&#39;s scale&quot;">​</a></h3><ul><li><strong>Read-only MD</strong> for specs, plans, CLAUDE.md, skills, roles: correct. These are documentation.</li><li><strong>Short-throw MD</strong> for WORK_STREAM: acceptable if single-writer (incorporator) or claim-before-edit discipline.</li><li><strong>JSONL</strong> for append-only event streams (run_registry, evidence_ledger, backlog): appropriate. No need for SQL.</li></ul><hr><h2 id="sqlite-db-backed" tabindex="-1">SQLite / DB-Backed <a class="header-anchor" href="#sqlite-db-backed" aria-label="Permalink to &quot;SQLite / DB-Backed&quot;">​</a></h2><h3 id="when-db-helps" tabindex="-1">When DB Helps <a class="header-anchor" href="#when-db-helps" aria-label="Permalink to &quot;When DB Helps&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Use Case</th><th>Why DB</th></tr></thead><tbody><tr><td><strong>High write concurrency</strong></td><td>Many agents claiming/updating simultaneously; need row-level locking.</td></tr><tr><td><strong>Complex queries</strong></td><td>&quot;All items where Depends satisfied and Priority=P0 and not in CLAIMED&quot; — SQL is cleaner.</td></tr><tr><td><strong>Referential integrity</strong></td><td>Depends → BACKLOG.id; COMPLETED.id must exist in BACKLOG.</td></tr><tr><td><strong>Time-series analytics</strong></td><td>&quot;Tasks completed per day&quot;, &quot;stale rate by source&quot; — SQL aggregations.</td></tr><tr><td><strong>Cross-store joins</strong></td><td>WORK_STREAM + run_registry + backlog.jsonl in one query.</td></tr></tbody></table><h3 id="when-db-hurts" tabindex="-1">When DB Hurts <a class="header-anchor" href="#when-db-hurts" aria-label="Permalink to &quot;When DB Hurts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Drawback</th><th>Impact</th></tr></thead><tbody><tr><td><strong>Operational burden</strong></td><td>SQLite file in <code>.thegent/</code> — backup, migration, corruption recovery.</td></tr><tr><td><strong>Git opacity</strong></td><td>DB not diffable. Lose &quot;what changed&quot; in code review.</td></tr><tr><td><strong>Portability</strong></td><td>Need sqlite3 binary. Sandbox/CI may restrict.</td></tr><tr><td><strong>Abstraction tax</strong></td><td>All readers need DB layer. Today: <code>read_text()</code> + parse.</td></tr><tr><td><strong>Overkill</strong></td><td>Backlog ~100–1000 items; JSONL + in-memory filter is fine.</td></tr></tbody></table><h3 id="verdict-sqlite-not-recommended-for-current-scope" tabindex="-1">Verdict: SQLite <strong>not recommended</strong> for current scope <a class="header-anchor" href="#verdict-sqlite-not-recommended-for-current-scope" aria-label="Permalink to &quot;Verdict: SQLite **not recommended** for current scope&quot;">​</a></h3><ul><li>thegent is single-user/single-session or low-concurrency multi-agent.</li><li>Claim coordination (CLAIMED table) works with file-based discipline.</li><li>Event volumes (run_registry, evidence) are append-only; JSONL is sufficient.</li><li><strong>Revisit</strong> if: &gt;10 agents writing concurrently, or analytics/reporting needs grow.</li></ul><hr><h2 id="harmonious-integration-single-conceptual-model" tabindex="-1">Harmonious Integration: Single Conceptual Model <a class="header-anchor" href="#harmonious-integration-single-conceptual-model" aria-label="Permalink to &quot;Harmonious Integration: Single Conceptual Model&quot;">​</a></h2><p>All touchpoints should share one <strong>conceptual model</strong> even if storage is split:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>                    │              UNIFIED WORK STREAM (conceptual)           │</span></span>
<span class="line"><span>                    │  BACKLOG | CLAIMED | COMPLETED | Sources | Triggers     │</span></span>
<span class="line"><span>                    └─────────────────────────────────────────────────────────┘</span></span>
<span class="line"><span>                                         │</span></span>
<span class="line"><span>         ┌───────────────────────────────┼───────────────────────────────┐</span></span>
<span class="line"><span>         │                               │                               │</span></span>
<span class="line"><span>         ▼                               ▼                               ▼</span></span>
<span class="line"><span>┌─────────────────┐           ┌─────────────────┐           ┌─────────────────┐</span></span>
<span class="line"><span>│  MD (read-only) │           │  MD (short-throw)│           │  JSONL (append) │</span></span>
<span class="line"><span>│  CLAUDE.md      │           │  WORK_STREAM.md  │           │  run_registry   │</span></span>
<span class="line"><span>│  skills/*.md    │           │  specs/          │           │  backlog.jsonl  │</span></span>
<span class="line"><span>│  agents/*.md    │           │  pending-handoff │           │  evidence_ledger│</span></span>
<span class="line"><span>│  plans/*.md     │           │                  │           │  handoff_registry│</span></span>
<span class="line"><span>└────────┬────────┘           └────────┬──────────┘           └────────┬────────┘</span></span>
<span class="line"><span>         │                             │                               │</span></span>
<span class="line"><span>         └─────────────────────────────┼───────────────────────────────┘</span></span>
<span class="line"><span>                                       │</span></span>
<span class="line"><span>         ┌─────────────────────────────┼─────────────────────────────┐</span></span>
<span class="line"><span>         │                             │                             │</span></span>
<span class="line"><span>         ▼                             ▼                             ▼</span></span>
<span class="line"><span>┌─────────────────┐           ┌─────────────────┐           ┌─────────────────┐</span></span>
<span class="line"><span>│  MCP            │           │  CLI             │           │  Headless       │</span></span>
<span class="line"><span>│  tools/resources│           │  plan next     │           │  triggers       │</span></span>
<span class="line"><span>│  prompts        │           │  govern go cycle  │           │  AgilePlus      │</span></span>
<span class="line"><span>│                 │           │  plan incorporate│           │  gardener-loop  │</span></span>
<span class="line"><span>└─────────────────┘           └─────────────────┘           └─────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><h3 id="integration-rules" tabindex="-1">Integration Rules <a class="header-anchor" href="#integration-rules" aria-label="Permalink to &quot;Integration Rules&quot;">​</a></h3><ol><li><strong>Single source of truth for work items</strong>: <code>WORK_STREAM.md</code>. MCP <code>thegent_do_next</code>, CLI <code>plan next</code>, skills (gardening), and AgilePlus planner all read it.</li><li><strong>Single source of truth for workflow instructions</strong>: <code>CLAUDE.md</code> + <code>thegent://workflow/triggers</code>, <code>thegent://workflow/gardening</code>. Skills and MCP prompts reference these; no duplication.</li><li><strong>Triggers fire the same cycle</strong>: Headless (timer/watchdog), gardener (Stop/time-based), and manual (<code>govern go cycle</code>) all invoke AgilePlusLoop. Same backlog, same evidence ledger.</li><li><strong>Roles and skills are read-only config</strong>: <code>agents/*.md</code> and <code>skills/*/SKILL.md</code> are loaded by runner; no runtime mutation. MD is correct.</li><li><strong>Event streams stay append-only</strong>: run_registry, evidence_ledger, backlog.jsonl — JSONL. No DB.</li></ol><hr><h2 id="recommendations" tabindex="-1">Recommendations <a class="header-anchor" href="#recommendations" aria-label="Permalink to &quot;Recommendations&quot;">​</a></h2><h3 id="keep-no-change" tabindex="-1">Keep (No Change) <a class="header-anchor" href="#keep-no-change" aria-label="Permalink to &quot;Keep (No Change)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Rationale</th></tr></thead><tbody><tr><td>WORK_STREAM.md as canonical backlog</td><td>MD, git-friendly, human-editable. Incorporator is single writer for merge.</td></tr><tr><td>JSONL for run_registry, evidence_ledger, backlog</td><td>Append-only, audit trail, no schema migration.</td></tr><tr><td>CLAUDE.md, skills, roles as MD</td><td>Read-only config. Perfect for MD.</td></tr><tr><td>MCP resources <code>thegent://workflow/*</code></td><td>URI-addressable; agents read when needed.</td></tr></tbody></table><h3 id="add-harmonize" tabindex="-1">Add (Harmonize) <a class="header-anchor" href="#add-harmonize" aria-label="Permalink to &quot;Add (Harmonize)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>Action</th></tr></thead><tbody><tr><td><strong>Trigger → WORK_STREAM</strong></td><td>When gardener detects <code>fragmented_research</code>, spawn incorporator. When AgilePlus ANALYZE completes, optionally merge backlog.jsonl into WORK_STREAM.</td></tr><tr><td><strong>MCP resource <code>thegent://workstream</code></strong></td><td>Expose WORK_STREAM.md (or summary) as read-only resource. Agents can <code>read_resource(&quot;thegent://workstream&quot;)</code> instead of file path.</td></tr><tr><td><strong>Skills reference WORK_STREAM</strong></td><td>In sitback-agent and agent-orchestra SKILL.md: &quot;Read WORK_STREAM.md or thegent_do_next for next items.&quot;</td></tr><tr><td><strong>CLAUDE.md trigger table</strong></td><td>Add row: <code>thegent://workstream</code> | Work stream (canonical backlog) | MCP resource</td></tr></tbody></table><h3 id="defer-revisit-later" tabindex="-1">Defer (Revisit Later) <a class="header-anchor" href="#defer-revisit-later" aria-label="Permalink to &quot;Defer (Revisit Later)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Item</th><th>When to Revisit</th></tr></thead><tbody><tr><td>SQLite for WORK_STREAM</td><td>&gt;10 concurrent writers; or need for complex reporting.</td></tr><tr><td>SQLite for run_registry</td><td>Compliance requirement for queryable audit; or &gt;100k events.</td></tr><tr><td>Unified DB for all state</td><td>Enterprise deployment with dedicated ops; multi-tenant.</td></tr></tbody></table><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Answer</th></tr></thead><tbody><tr><td><strong>MD as read-only / short-throw?</strong></td><td><strong>Yes.</strong> Keep specs, plans, CLAUDE.md, skills, roles as MD. WORK_STREAM as short-throw MD with single-writer discipline.</td></tr><tr><td><strong>SQLite/DB better?</strong></td><td><strong>Not for current scope.</strong> JSONL + MD sufficient. Revisit if concurrency or analytics demands it.</td></tr><tr><td><strong>Holistic tie-in?</strong></td><td><strong>Single conceptual model</strong>: WORK_STREAM = canonical backlog. All touchpoints (MCP, CLI, skill, triggers) read/write it or its derived views. Add <code>thegent://workstream</code> resource; wire triggers to incorporator.</td></tr></tbody></table><hr><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../reference/WORK_STREAM.html">WORK_STREAM.md</a> — canonical backlog</li><li><a href="./../plans/00-MASTER-INDEX.html">00-MASTER-INDEX.md</a> — plan index</li></ul><hr><h2 id="extension-summary" tabindex="-1">EXTENSION_SUMMARY <a class="header-anchor" href="#extension-summary" aria-label="Permalink to &quot;EXTENSION_SUMMARY&quot;">​</a></h2><p><strong>Extended on:</strong> 2026-02-17 <strong>Extended by:</strong> Claude Code</p><h3 id="changes-made" tabindex="-1">Changes Made <a class="header-anchor" href="#changes-made" aria-label="Permalink to &quot;Changes Made&quot;">​</a></h3><ol><li>Added practical implementation patterns</li><li>Added configuration examples</li><li>Enhanced cross-references to related documentation</li></ol><h3 id="cross-references-added" tabindex="-1">Cross-References Added <a class="header-anchor" href="#cross-references-added" aria-label="Permalink to &quot;Cross-References Added&quot;">​</a></h3><ul><li>Related research and implementation guides</li><li>WORK_STREAM.md for tracking</li></ul><h3 id="practical-additions" tabindex="-1">Practical Additions <a class="header-anchor" href="#practical-additions" aria-label="Permalink to &quot;Practical Additions&quot;">​</a></h3><ul><li>Implementation templates</li><li>Configuration examples</li><li>Best practices</li></ul>`,53)])])}const u=e(s,[["render",o]]);export{h as __pageData,u as default};
